lines+=['','| Dynamic measure | Target | Dry Ink Bristle | Result | Dry Paint | Result |','| --- | --- | ---: | :---: | ---: | :---: |']
for key in ['speed-opacity','speed-fray','pressure','curve']:
 a,b=[next(r for r in dynamics if r['key']==key and r['preset']==p)for p in ['dry-ink-bristle','dry-paint']];lines.append(f"| {a['measure']} | {a['target']} | {a['value']:.4f} | {'PASS'if a['pass']else'FAIL'} | {b['value']:.4f} | {'PASS'if b['pass']else'FAIL'} |")
