 a,b,c=r['replay600px'],r['pointerEvent'],r['toothDirtyBox'];lines.append(f"| {r['preset']} / {r['shape']} | {a['mean']:.2f} / {a['max']:.2f} — {'PASS'if r['targets']['replay120ms']else'FAIL'} | {b['mean']:.2f} / {b['p95']:.2f} / {b['max']:.2f} — {'PASS'if r['targets']['event3ms']else'FAIL'} | {c['mean']:.2f} / {c['max']:.2f} — {'PASS'if r['targets']['tooth2ms']else'FAIL'} |")
